17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.time.LocalDate;
20	import java.util.Locale;
21	import java.util.Set;
22	import java.util.regex.Pattern;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.rest.advice.OwnerRegistrationException;
30	import org.springframework.samples.petclinic.rest.advice.OwnerRegistrationException.Reason;
31	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
32	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
33	import org.springframework.samples.petclinic.service.ClinicService;
34	import org.springframework.samples.petclinic.util.HashUtils;
35	import org.springframework.samples.petclinic.util.IdentityUtils;
36	import org.springframework.stereotype.Component;
37	import org.springframework.web.util.UriComponentsBuilder;
38	
39	/**
40	 * Owns the owner-creation concern: the single place that turns a submitted
41	 * {@link OwnerFieldsDto} into a validated, normalized, enriched and persisted {@link Owner},
42	 * and reports the create outcome as the HTTP response the endpoint returns.
43	 *
44	 * <p>Keeping the whole create pipeline here means every rule that fires on create — the
45	 * registration-date and business-day handling, the per-day and per-city quotas, the
46	 * address/telephone/email/postcode normalization and validation, the household, duplicate
47	 * and soft-match identity rules, and the derived member id and namesake count — reads the
48	 * one owner this class builds, in the one order it applies
49	 * them, so they can never drift apart. The controller is left holding only the endpoint's
50	 * HTTP boundary.
51	 */
52	@Component
53	public class OwnerRegistrar {
54	
55	    /** Minimal syntactic check for an email address: a non-empty local part, a single
56	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
57	    private static final Pattern EMAIL_PATTERN =
58	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
59	
60	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
61	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final TelephoneNormalizer telephoneNormalizer;
68	
69	    private final AddressNormalizer addressNormalizer;
70	
71	    private final CityRegionResolver cityRegionResolver;
72	
73	    private final EmailDomainClassifier emailDomainClassifier;
74	
75	    private final HouseholdResolver householdResolver;
76	
77	    private final OwnerAuditor ownerAuditor;
78	
79	    private final WelcomeNotifier welcomeNotifier;
80	
81	    /**
82	     * Remembers, per {@code Idempotency-Key}, the id of the owner that key's create originally
83	     * produced, so a later create carrying the same key returns that same owner instead of
84	     * creating a duplicate. The registrar is a singleton, so this store outlives a single
85	     * request; entries are keyed by the client-supplied key, which is expected to be unique
86	     * per logical create.
87	     */
88	    private final java.util.concurrent.ConcurrentHashMap<String, Integer> idempotencyKeys =
89	        new java.util.concurrent.ConcurrentHashMap<>();
90	
91	    public OwnerRegistrar(ClinicService clinicService,
92	                          OwnerMapper ownerMapper,
93	                          TelephoneNormalizer telephoneNormalizer,
94	                          AddressNormalizer addressNormalizer,
95	                          CityRegionResolver cityRegionResolver,
96	                          EmailDomainClassifier emailDomainClassifier,
97	                          HouseholdResolver householdResolver,
98	                          OwnerAuditor ownerAuditor,
99	                          WelcomeNotifier welcomeNotifier) {
100	        this.clinicService = clinicService;
101	        this.ownerMapper = ownerMapper;
102	        this.telephoneNormalizer = telephoneNormalizer;
103	        this.addressNormalizer = addressNormalizer;
104	        this.cityRegionResolver = cityRegionResolver;
105	        this.emailDomainClassifier = emailDomainClassifier;
106	        this.householdResolver = householdResolver;
107	        this.ownerAuditor = ownerAuditor;
108	        this.welcomeNotifier = welcomeNotifier;
109	    }
110	
111	    /**
112	     * Validate, normalize, enrich and persist a new owner from the submitted fields, and
113	     * report success as the response the create endpoint returns: {@code 201 Created} (with a
114	     * {@code Location} header and the created owner). When a create rule refuses the request the
115	     * method throws {@link OwnerRegistrationException}, whose {@link OwnerRegistrationException.Reason}
116	     * carries the rejection status ({@code 400}, {@code 409} or {@code 429}); no owner is persisted
117	     * unless every rule passes.
118	     *
119	     * @param ownerFieldsDto the submitted owner fields
120	     * @return the created owner as a {@code 201 Created} response
121	     * @throws OwnerRegistrationException when a create rule refuses the request
122	     */
123	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto) {
124	        return register(ownerFieldsDto, null);
125	    }
126	
127	    /**
128	     * As {@link #register(OwnerFieldsDto)}, but honouring an optional {@code Idempotency-Key}.
129	     * When {@code idempotencyKey} is non-blank and a create with that key has already succeeded,
130	     * the owner it originally produced is returned with {@code 200 OK} instead of creating a
131	     * duplicate. Otherwise the normal create pipeline runs and, on success, the key is recorded
132	     * against the created owner so a later repeat resolves to the same owner.
133	     *
134	     * @param ownerFieldsDto the submitted owner fields
135	     * @param idempotencyKey the request's {@code Idempotency-Key} header, or {@code null} when absent
136	     * @return the created (or previously created) owner as a {@code 201 Created} or {@code 200 OK} response
137	     * @throws OwnerRegistrationException when a create rule refuses the request
138	     */
139	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
140	        String key = (idempotencyKey == null || idempotencyKey.isBlank()) ? null : idempotencyKey.trim();
141	        if (key != null) {
142	            Integer existingId = idempotencyKeys.get(key);
143	            if (existingId != null) {
144	                Owner original = this.clinicService.findOwnerById(existingId);
145	                if (original != null) {
146	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(original), HttpStatus.OK);
147	                }
148	                // The originally created owner is gone; forget the stale key and create afresh.
149	                idempotencyKeys.remove(key);
150	            }
151	        }
152	        HttpHeaders headers = new HttpHeaders();
153	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
154	        if (owner.getRegistrationDate() == null) {
155	            owner.setRegistrationDate(LocalDate.now());
156	        }
157	        // A supplied registration date may not be later than the server's current date.
158	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
159	            throw new OwnerRegistrationException(Reason.REGISTRATION_DATE_IN_FUTURE);
160	        }
161	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
162	        LocalDate registrationDate = owner.getRegistrationDate();
163	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
164	            .map(Owner::getRegistrationDate)
165	            .filter(registrationDate::equals)
166	            .count();
167	        if (ownersCreatedThatDay >= 100) {
168	            throw new OwnerRegistrationException(Reason.DAILY_CREATE_LIMIT_REACHED);
169	        }
170	        String address = normalizedAddress(owner);
171	        if (address == null) {
172	            throw new OwnerRegistrationException(Reason.ADDRESS_MISSING);
173	        }
174	        owner.setAddress(address);
175	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
176	        if (telephone == null) {
177	            throw new OwnerRegistrationException(Reason.TELEPHONE_INVALID);
178	        }
179	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
180	            throw new OwnerRegistrationException(Reason.TELEPHONE_INVALID);
181	        }
182	        owner.setTelephone(telephone);
183	        String email = owner.getEmail();
184	        if (email != null) {
185	            email = email.trim();
186	            if (!EMAIL_PATTERN.matcher(email).matches()) {
187	                throw new OwnerRegistrationException(Reason.EMAIL_INVALID);
188	            }
189	            if (emailDomainClassifier.isDisposable(email)) {
190	                throw new OwnerRegistrationException(Reason.EMAIL_DISPOSABLE);
191	            }
192	            owner.setEmail(email.toLowerCase(Locale.ROOT));
193	        }
194	        // A postcode is optional, but when supplied it must be four digits and valid for the
195	        // owner's city per the fixed region table; a city with no known region accepts any
196	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
197	        String postcode = owner.getPostcode();
198	        if (postcode != null) {
199	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
200	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
201	                throw new OwnerRegistrationException(Reason.POSTCODE_INVALID);
202	            }
203	        }
204	        // The owner's telephone and email are now in their canonical, stored form.
205	        // The household id is deterministic: owners with the same normalized last name and
206	        // postcode share it automatically. Assign it unconditionally so the membership-level
207	        // ceiling can key off it; it no longer participates in duplicate detection, which now
208	        // rests solely on the identity key below.
209	        owner.setHouseholdId(householdResolver.householdId(owner));
210	        // Duplicate detection is the single identity key: a candidate is rejected only when its
211	        // whole identityKey (normalized telephone, lower-cased email and soundex of the last name)
212	        // collides with a non-deleted owner's. Two people sharing a household with different
213	        // telephones therefore derive different keys and are both admitted; the second is instead
214	        // flagged as a possible duplicate by the soft-match rule below.
215	        if (isDuplicateOwner(owner)) {
216	            throw new OwnerRegistrationException(Reason.DUPLICATE_OWNER);
217	        }
218	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
219	        long ownersInCity = this.clinicService.findAllOwners().stream()
220	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
221	            .count();
222	        if (ownersInCity >= 50) {
223	            throw new OwnerRegistrationException(Reason.CITY_CAPACITY_REACHED);
224	        }
225	        // Approaching-capacity warning: the city already holds 40-49 owners (the hard limit is 50,
226	        // rejected above). ownersInCity counts the existing owners the candidate is joining.
227	        owner.setCapacityWarning(ownersInCity >= 40 && ownersInCity < 50);
228	        owner.setMemberId(memberId(owner));
229	        owner.setNamesakeCount(namesakeCount(owner));
230	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
231	        // Soft-match: the candidate has already cleared the hard-duplicate check, but its
232	        // identityKey may still differ from an existing owner's while their last names sound alike
233	        // (equal soundex) and their postcodes match — a likely re-registration of the same person
234	        // under a different telephone or email. When it does, it is created but flagged as a
235	        // possible duplicate of that existing owner; otherwise the flag is false and no reference
236	        // is recorded.
237	        Integer possibleDuplicateOf = possibleDuplicateOf(owner);
238	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
239	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
240	        this.clinicService.saveOwner(owner);
241	        if (key != null) {
242	            idempotencyKeys.put(key, owner.getId());
243	        }
244	        ownerAuditor.ownerCreated(owner, ownerMapper.membershipLevel(owner));
245	        welcomeNotifier.welcome(owner);
246	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
247	        headers.setLocation(UriComponentsBuilder.newInstance()
248	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
249	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
250	    }
251	
252	    /**
253	     * The owner's postal address in the single canonical form under which it is stored, or
254	     * {@code null} when the owner supplies no usable address. An owner may supply its address
255	     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
256	     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
257	     *
258	     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
259	     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
260	     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
261	     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
262	     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
263	     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
264	     * (no usable address in either form) has no canonical form and is reported as {@code null} so
265	     * the caller can reject the request with 400.
266	     *
267	     * <p>This is the single point at which an owner's address is resolved and normalized on
268	     * create, so every rule keyed on the stored address reads the one value produced here.
269	     *
270	     * @param owner the owner about to be created
271	     * @return the canonical stored address, or {@code null} when the owner supplies none
272	     */
273	    private String normalizedAddress(Owner owner) {
274	        String rawLine1 = owner.getAddressLine1();
275	        if (rawLine1 != null && !rawLine1.isBlank()) {
276	            String line1 = addressNormalizer.normalize(rawLine1);
277	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
278	            owner.setAddressLine1(line1);
279	            owner.setAddressLine2(line2.isBlank() ? null : line2);
280	            return line2.isBlank() ? line1 : line1 + " " + line2;
281	        }
282	        owner.setAddressLine1(null);
283	        owner.setAddressLine2(null);
284	        String address = addressNormalizer.normalize(owner.getAddress());
285	        return address.isBlank() ? null : address;
286	    }
287	
288	    /**
289	     * Whether {@code candidate} collides with an already-registered owner under the single
290	     * identity rule enforced on create. This is the one point at which a new owner is
291	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
292	     * derived {@link OwnerMapper#identityKey identityKey} — the SHA-256 hex over the normalized
293	     * telephone, the lower-cased email (or an empty string when absent) and the soundex of the
294	     * last name, joined by '|'. The candidate clashes only when its WHOLE identityKey equals an
295	     * existing owner's; because the telephone is part of the key, two people sharing a household
296	     * (a like-sounding last name and postcode) with different telephones have different
297	     * identityKeys and are both allowed.
298	     *
299	     * <p>The candidate arrives with its telephone and email already normalized, and each existing
300	     * owner is stored in the same canonical form, so an identityKey match means the two owners are
301	     * genuinely the same identity.
302	     *
303	     * @param candidate the fully-normalized owner about to be created
304	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
305	     */
306	    private boolean isDuplicateOwner(Owner candidate) {
307	        String identityKey = OwnerMapper.identityKey(candidate);
308	        return this.clinicService.findAllOwners().stream()
309	            .filter(existing -> !existing.isDeleted())
310	            .map(OwnerMapper::identityKey)
311	            .anyMatch(identityKey::equals);
312	    }
313	
314	    /**
315	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
316	     * {@code null} when there is none. A soft match is an owner whose whole identityKey differs
317	     * from the candidate's (so it is not a hard duplicate) yet whose last name sounds alike (equal
318	     * {@link IdentityUtils#soundex soundex}) and whose postcode matches — a likely re-registration
319	     * of the same person under a different telephone or email. Both must supply a postcode for a
320	     * match to be possible; when several existing owners qualify the lowest id is returned so the
321	     * result is deterministic.
322	     *
323	     * @param candidate the fully-normalized owner about to be created
324	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
325	     */
326	    private Integer possibleDuplicateOf(Owner candidate) {
327	        String postcode = candidate.getPostcode();
328	        if (postcode == null || postcode.isBlank()) {
329	            return null;
330	        }
331	        String identityKey = OwnerMapper.identityKey(candidate);
332	        String lastNameSoundex = IdentityUtils.soundex(candidate.getLastName());
333	        return this.clinicService.findAllOwners().stream()
334	            .filter(existing -> !existing.isDeleted()
335	                && !identityKey.equals(OwnerMapper.identityKey(existing))
336	                && IdentityUtils.soundex(existing.getLastName()).equals(lastNameSoundex)
337	                && postcode.equals(existing.getPostcode()))
338	            .map(Owner::getId)
339	            .filter(java.util.Objects::nonNull)
340	            .min(Integer::compareTo)
341	            .orElse(null);
342	    }
343	
344	    /**
345	     * Build the member id assigned to {@code owner} on create, formatted
346	     * {@code '<REGION><FY><HASH8><CHK>'}: REGION is the region code derived from the owner's
347	     * postcode (falling back to the city) via {@link CityRegionResolver}, FY is the two-digit
348	     * fiscal year of the (business-day-adjusted) registrationDate (the fiscal year starts on
349	     * 1 July), HASH8 is the first eight upper-case hex characters of the SHA-256 digest of the
350	     * normalized telephone concatenated with the last name (the same HASH8 used by the
351	     * region-and-hash identity), and CHK is a single Luhn check digit computed over the digits
352	     * of {@code '<REGION><FY><HASH8>'} (e.g. 'NSW261A2B3C4D5').
353	     *
354	     * <p>When the computed id collides with an already-registered owner's memberId it is
355	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
356	     * makes it unique (e.g. 'NSW261A2B3C4D5-2'), and the unique id is returned.
357	     */
358	    private String memberId(Owner owner) {
359	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
360	        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
361	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
362	        String core = region + fy + hash8;
363	        String base = core + OwnerMapper.luhn(core);
364	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
365	            .map(Owner::getMemberId)
366	            .filter(java.util.Objects::nonNull)
367	            .collect(java.util.stream.Collectors.toSet());
368	        return disambiguate(base, existing);
369	    }
370	
371	    /**
372	     * Make {@code base} unique among the {@code existing} identity codes: return it unchanged when
373	     * it is free, otherwise append {@code '-<n>'} with the smallest {@code n} of 2 or more that is
374	     * not already taken (e.g. 'NSW-1A2B3C4D-2'). This is the single de-duplication step an assigned
375	     * identity code passes through, so a collision is broken the one way wherever a code is built.
376	     */
377	    private static String disambiguate(String base, java.util.Set<String> existing) {
378	        if (!existing.contains(base)) {
379	            return base;
380	        }
381	        int n = 2;
382	        while (existing.contains(base + "-" + n)) {
383	            n++;
384	        }
385	        return base + "-" + n;
386	    }
387	
388	    /**
389	     * The number of existing owners that share {@code owner}'s firstName and lastName,
390	     * compared case-insensitively. The candidate is not yet stored at the point this is
391	     * assigned, so it does not count itself. This is the value stored as the owner's
392	     * namesakeCount on create.
393	     */
394	    private int namesakeCount(Owner owner) {
395	        return (int) this.clinicService.findAllOwners().stream()
396	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
397	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
398	            .count();
399	    }
400	
401	    /** Fixed list of public holidays that a registration date must roll past. */
402	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
403	        LocalDate.of(2026, 1, 1),
404	        LocalDate.of(2026, 1, 26),
405	        LocalDate.of(2026, 4, 25),
406	        LocalDate.of(2026, 12, 25),
407	        LocalDate.of(2026, 12, 28));
408	
409	    /**
410	     * Roll a registration date forward to the next business day: a Saturday, Sunday
411	     * or listed public holiday advances one day at a time until it lands on a weekday
412	     * that is not a public holiday. A plain weekday is returned unchanged.
413	     */
414	    private static LocalDate toBusinessDay(LocalDate date) {
415	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
416	            date = date.plusDays(1);
417	        }
418	        return date;
419	    }
420	
421	    private static boolean isWeekend(LocalDate date) {
422	        return switch (date.getDayOfWeek()) {
423	            case SATURDAY, SUNDAY -> true;
424	            default -> false;
425	        };
426	    }
427	}
