56	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
57	    @Mapping(target = "initials", expression = "java(initials(owner))")
58	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
59	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
60	    @Mapping(target = "locality", expression = "java(locality(owner))")
61	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
62	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
63	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneNormalizer.toDisplayForm(owner.getTelephone()))")
64	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
65	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
66	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
67	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
68	    @Mapping(target = "riskFlag", expression = "java(riskFlag(owner))")
69	    public abstract OwnerDto toOwnerDto(Owner owner);
70	
71	    /**
72	     * The owner's risk flag: {@code true} when any of the three risk signals holds, {@code false}
73	     * otherwise. The signals are that the owner is a possible duplicate (its stored
74	     * {@code possibleDuplicate} is true), that its email domain is
75	     * {@link EmailDomainClassifier#isDisposableAdjacent disposable-adjacent}, or that its city is
76	     * {@link #cityOverSoftCapacity over its soft capacity}.
77	     */
78	    boolean riskFlag(Owner owner) {
79	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
80	            || emailDomainClassifier.isDisposableAdjacent(owner.getEmail())
81	            || cityOverSoftCapacity(owner);
82	    }
83	
84	    /**
85	     * Whether the owner's city currently holds more than its soft capacity of
86	     * {@value #CITY_SOFT_CAPACITY} owners. Cities are compared on their normalized identity, the
87	     * same key the create endpoint's per-city capacity rule uses, so the same owners are counted.
88	     */
89	    boolean cityOverSoftCapacity(Owner owner) {
90	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
91	        long ownersInCity = clinicService.findAllOwners().stream()
92	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
93	            .count();
94	        return ownersInCity > CITY_SOFT_CAPACITY;
95	    }
96	
97	    /**
98	     * The owner's self link: '/api/owners/' followed by the owner's id, or null when the
99	     * owner has no id assigned yet.
100	     */
101	    String selfLink(Owner owner) {
102	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
103	    }
104	
105	    /**
106	     * The fiscal year (starting 1 July) that {@code date} falls in, identified by the
107	     * calendar year in which the fiscal year ends: a date in July–December belongs to the
108	     * fiscal year ending the following calendar year, while January–June belongs to the one
109	     * ending that same calendar year.
110	     */
111	    public static int fiscalYear(LocalDate date) {
112	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
113	    }
114	
115	    /**
116	     * The owner's fiscal year formatted 'FY<YY>', where YY is the two-digit FY segment carried by
117	     * the owner's assigned memberId (see {@link #memberIdCore}). When no memberId has been assigned
118	     * this falls back to the fiscal year of the (business-day-adjusted) {@code registrationDate}
119	     * (the fiscal year starts on 1 July), and returns null when there is no registrationDate either.
120	     */
121	    String fiscalYear(Owner owner) {
122	        String core = memberIdCore(owner.getMemberId());
123	        if (core != null && core.length() > 11) {
124	            return "FY" + core.substring(core.length() - 11, core.length() - 9);
125	        }
126	        LocalDate registrationDate = owner.getRegistrationDate();
127	        if (registrationDate == null) {
128	            return null;
129	        }
130	        return String.format("FY%02d", fiscalYear(registrationDate) % 100);
131	    }
132	
133	    /**
134	     * The owner's age band derived from {@code birthDate} relative to the
135	     * {@code registrationDate}: 'MINOR' when under 18, 'ADULT' from 18 to 64
136	     * inclusive and 'SENIOR' at 65 or older. Returns null when either date is
137	     * absent so no band can be computed.
138	     */
139	    OwnerDto.AgeBandEnum ageBand(Owner owner) {
140	        LocalDate birthDate = owner.getBirthDate();
141	        LocalDate registrationDate = owner.getRegistrationDate();
142	        if (birthDate == null || registrationDate == null) {
143	            return null;
144	        }
145	        int age = Period.between(birthDate, registrationDate).getYears();
146	        if (age < 18) {
147	            return OwnerDto.AgeBandEnum.MINOR;
148	        }
149	        if (age < 65) {
150	            return OwnerDto.AgeBandEnum.ADULT;
151	        }
152	        return OwnerDto.AgeBandEnum.SENIOR;
153	    }
154	
155	    /**
156	     * The Luhn check digit (0-9) over the digits contained in {@code s}: from the rightmost
157	     * digit leftward, every second digit is doubled (the rightmost first) with digits over 9
158	     * reduced by 9, and the check digit makes the total a multiple of ten.
159	     *
160	     * <p>This is the single Luhn derivation behind the application's identity values; like
161	     * {@link #fiscalYear(LocalDate)} and {@link #identityKey(Owner)} it is exposed so the check
162	     * digit is computed the one way wherever an identifier is assembled, including outside this
163	     * package.
164	     */
165	    public static int luhn(String s) {
166	        int sum = 0;
167	        boolean doubling = true;
168	        for (int i = s.length() - 1; i >= 0; i--) {
169	            char c = s.charAt(i);
170	            if (c < '0' || c > '9') {
171	                continue;
172	            }
173	            int d = c - '0';
174	            if (doubling) {
175	                d *= 2;
176	                if (d > 9) {
177	                    d -= 9;
178	                }
179	            }
180	            sum += d;
181	            doubling = !doubling;
182	        }
183	        return (10 - (sum % 10)) % 10;
184	    }
185	
186	    /**
187	     * The owner's derived identity key: the SHA-256 hex digest of the normalized telephone,
188	     * the lower-cased email (or an empty string when absent) and the {@link IdentityUtils#soundex
189	     * soundex} of the last name, joined by '|'. This single key is the sole basis for duplicate
190	     * detection on create — two owners are duplicates only when their whole identityKey matches,
191	     * so two people sharing a household (a like-sounding last name and postcode) but carrying
192	     * different telephones derive different keys and are all permitted.
193	     */
194	    public static String identityKey(Owner owner) {
195	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
196	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
197	        String lastNameSoundex = IdentityUtils.soundex(owner.getLastName());
198	        return HashUtils.sha256Hex(telephone + "|" + email + "|" + lastNameSoundex);
199	    }
200	
201	    /**
202	     * The owner's preferred contact channel: 'EMAIL' when an email address is
203	     * present, otherwise 'PHONE'.
204	     */
205	    String contactPreference(Owner owner) {
206	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
207	        return hasEmail ? "EMAIL" : "PHONE";
208	    }
209	
210	    /**
211	     * The memberId's core: the {@code '<REGION><FY><HASH8><CHK>'} carried by the owner's assigned
212	     * memberId, with any de-duplication {@code '-<n>'} suffix stripped, or null when no memberId has
213	     * been assigned. This is the single place the stored identifier is split back into its fixed
214	     * segments (a trailing FY of 2, HASH8 of 8 and CHK of 1 — eleven characters — following the
215	     * variable-length region), so every rule keyed on a segment reads it the one way.
216	     */
217	    private static String memberIdCore(String memberId) {
218	        if (memberId == null) {
219	            return null;
220	        }
221	        int dash = memberId.indexOf('-');
222	        return dash >= 0 ? memberId.substring(0, dash) : memberId;
223	    }
224	
225	    /**
226	     * The REGION segment carried by the owner's assigned memberId: the part of its
227	     * {@link #memberIdCore core} before the fixed trailing FY(2) + HASH8(8) + CHK(1). Returns null
228	     * when no memberId has been assigned, or when it carries no region segment.
229	     */
230	    private String identityRegion(Owner owner) {
231	        String core = memberIdCore(owner.getMemberId());
232	        return core != null && core.length() > 11 ? core.substring(0, core.length() - 11) : null;
233	    }
234	
235	    /**
236	     * The owner's locality: the REGION segment of its assigned identity code (see
237	     * {@link #identityRegion}). When no code has been assigned this falls back to the canonical
238	     * region derived from the owner via {@link CityRegionResolver}, preferring the postcode over the
239	     * city, or 'UNKNOWN' when neither yields a known region.
240	     */
241	    String locality(Owner owner) {
242	        String region = identityRegion(owner);
243	        return region != null ? region : cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
244	    }
245	
246	    /**
247	     * The owner's segment, formatted '&lt;TIER&gt;_&lt;AREA&gt;'. TIER is 'PREMIUM' when the owner's
248	     * {@link #membershipLevel(Owner) membershipLevel} is 3 or more, otherwise 'STANDARD'. AREA is
249	     * 'METRO' when the owner's {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD),
250	     * otherwise 'REGIONAL'.
251	     */
252	    OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
253	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
254	        boolean knownRegion = cityRegionResolver.timezoneForRegion(locality(owner)) != null;
255	        String area = knownRegion ? "METRO" : "REGIONAL";
256	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
257	    }
258	
259	    /**
260	     * The owner's IANA timezone name derived from the owner's {@link #locality(Owner) locality}
261	     * via the fixed region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
262	     * QLD -> Australia/Brisbane). Returns null when the locality is not a region in the table.
263	     */
264	    String timezone(Owner owner) {
265	        return cityRegionResolver.timezoneForRegion(locality(owner));
266	    }
267	
268	    /**
269	     * The owner's membership points: starting at 0, plus 2 when an email address is present,
270	     * plus 1 when namesakeCount is 0, plus 2 for a household of 3 or more members, plus 3 when
271	     * the owner's tenure is more than one fiscal year.
272	     */
273	    public int membershipPoints(Owner owner) {
274	        int points = 0;
275	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
276	        if (hasEmail) {
277	            points += 2;
278	        }
279	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
280	        if (uniqueName) {
281	            points += 1;
282	        }
283	        if (householdSize(owner) >= 3) {
284	            points += 2;
285	        }
286	        LocalDate registrationDate = owner.getRegistrationDate();
287	        boolean tenured = registrationDate != null
288	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
289	        if (tenured) {
290	            points += 3;
291	        }
292	        return points;
293	    }
294	
295	    /**
296	     * The owner's numeric membership level from 1 to 4, derived from {@link #membershipPoints}
297	     * via {@link #levelForPoints} and then held to the household level-ceiling by
298	     * {@link #cappedByHousehold}.
299	     */
300	    public int membershipLevel(Owner owner) {
301	        return cappedByHousehold(owner, levelForPoints(membershipPoints(owner)));
302	    }
303	
304	    /**
305	     * Hold {@code level} to the household level-ceiling: an owner's membershipLevel may not exceed
306	     * one above the current maximum membershipLevel among the household members that already
307	     * existed when this owner registered — the other, non-deleted owners sharing its householdId
308	     * that were created earlier (a strictly lower id, ids being monotonic). When no such earlier
309	     * household member exists no ceiling applies and {@code level} is returned unchanged.
310	     *
311	     * @param owner the owner whose own level is being capped
312	     * @param level the owner's uncapped membership level
313	     * @return the level, capped at one above the earlier household members' maximum
314	     */
315	    private int cappedByHousehold(Owner owner, int level) {
316	        Integer id = owner.getId();
317	        String householdId = owner.getHouseholdId();
318	        if (id == null || householdId == null) {
319	            return level;
320	        }
321	        OptionalInt maxExisting = clinicService.findAllOwners().stream()
322	            .filter(existing -> !existing.isDeleted())
323	            .filter(existing -> existing.getId() != null && existing.getId() < id)
324	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
325	            .mapToInt(this::membershipLevel)
326	            .max();
327	        return maxExisting.isEmpty() ? level : Math.min(level, maxExisting.getAsInt() + 1);
328	    }
329	
330	    /**
331	     * The numeric membership level from 1 to 4 that {@code points} maps to: level 1 for 0-1
332	     * points, level 2 for 2-3 points, level 3 for 4-5 points and level 4 for 6 or more points.
333	     */
334	    int levelForPoints(int points) {
335	        if (points >= 6) {
336	            return 4;
337	        }
338	        if (points >= 4) {
339	            return 3;
340	        }
341	        if (points >= 2) {
342	            return 2;
343	        }
344	        return 1;
345	    }
346	
347	    /**
348	     * The owners belonging to {@code owner}'s household, i.e. those sharing its householdId
349	     * (including the owner itself once persisted). Returns an empty list when the owner has no
350	     * household id assigned.
351	     */
352	    List<Owner> householdMembers(Owner owner) {
353	        String householdId = owner.getHouseholdId();
354	        if (householdId == null) {
355	            return List.of();
356	        }
357	        return clinicService.findAllOwners().stream()
358	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
359	            .toList();
360	    }
361	
362	    /**
363	     * The number of owners belonging to {@code owner}'s household, i.e. those sharing its
364	     * householdId (including the owner itself once persisted). Returns 0 when the owner has no
365	     * household id assigned.
366	     */
367	    int householdSize(Owner owner) {
368	        return householdMembers(owner).size();
369	    }
370	
371	    /**
372	     * The owner's salutation: the {@code title} and last name separated by a single space
373	     * (e.g. 'DR who'), or just the last name when no title has been supplied.
374	     */
375	    String salutation(Owner owner) {
376	        String title = owner.getTitle();
377	        if (title == null || title.isBlank()) {
378	            return owner.getLastName();
379	        }
380	        return title + " " + owner.getLastName();
381	    }
382	
383	    /**
384	     * The upper-cased first letters of firstName and lastName, dot-separated with a
385	     * trailing dot, e.g. 'J.S.'.
386	     */
387	    String initials(Owner owner) {
388	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
389	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
390	    }
391	
392	    public abstract Owner toOwner(OwnerDto ownerDto);
393	
394	    @Mapping(target = "id", ignore = true)
395	    @Mapping(target = "pets", ignore = true)
396	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
397	
398	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
399	
400	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
401	
402	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
403	        OwnerPageDto ownerPageDto = new OwnerPageDto();
404	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
405	        ownerPageDto.setPage(ownerPage.getNumber());
406	        ownerPageDto.setSize(ownerPage.getSize());
407	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
408	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
409	        return ownerPageDto;
410	    }
411	}
